/**
 * bot-commander.js
 *
 * Receives tactical calls generated by enemy-coach.js and injects them into
 * the CS2 server via the CS2AiCoachPlugin HTTP endpoint (port 27016).
 *
 * Architecture note:
 *   This module is intentionally separate from the AI decision layer so that
 *   the execution backend can be swapped or extended without touching the
 *   coaching logic.
 *
 * Flow:
 *   enemy-coach.js → executeCall() → POST http://cs2:27016/bot-command
 *                                         ↓
 *                                  CS2AiCoachPlugin.cs
 *                                         ↓
 *                              Server.ExecuteCommand() on bots
 */

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

const CS2_URL = process.env.CS2_CONTAINER_URL || 'http://cs2:27016';

// ---------------------------------------------------------------------------
// Execute call
// ---------------------------------------------------------------------------

/**
 * Takes a tactical IGL call and injects it into the CS2 server via the
 * CounterStrikeSharp plugin HTTP endpoint.
 *
 * @param {string} call - Short tactical instruction produced by enemy-coach.js.
 * @param {import("./gsi-parser.js").GameState} gameState - Current game state.
 * @returns {Promise<void>}
 */
export async function executeCall(call, gameState) {
  const side   = gameState.enemyTeam?.side ?? 'T';
  const action = parseAction(call);

  console.log(`[BotCommander] Injecting call to ${side} bots: "${call}"`);
  console.log(`[BotCommander] Parsed action: ${action}`);

  try {
    const response = await fetch(`${CS2_URL}/bot-command`, {
      method:  'POST',
      headers: { 'Content-Type': 'application/json' },
      body:    JSON.stringify({ call, side, action }),
      signal:  AbortSignal.timeout(3000),
    });

    if (response.ok) {
      console.log(`[BotCommander] ✅ Command injected successfully`);
    } else {
      console.log(`[BotCommander] ⚠️ Command failed: HTTP ${response.status}`);
    }
  } catch (err) {
    console.log(`[BotCommander] ❌ Error sending command: ${err.message}`);
  }
}

// ---------------------------------------------------------------------------
// Action parser
// ---------------------------------------------------------------------------

/**
 * Maps a free-text tactical call to a structured action keyword that the C#
 * plugin understands.
 *
 * @param {string} call
 * @returns {'rush_b' | 'rush_a' | 'force_b' | 'save' | 'default'}
 */
function parseAction(call) {
  const lower = call.toLowerCase();

  if (lower.includes('force b') || lower.includes('force_b'))               return 'force_b';
  if (lower.includes('rush b')  || lower.includes('rush_b')  ||
      lower.includes('bomb b')  || lower.includes('execute b') ||
      lower.includes('site b')  || lower.includes(' b site'))               return 'rush_b';
  if (lower.includes('rush a')  || lower.includes('rush_a')  ||
      lower.includes('bomb a')  || lower.includes('execute a') ||
      lower.includes('site a')  || lower.includes(' a site'))               return 'rush_a';
  if (lower.includes('save')    || lower.includes('eco')     ||
      lower.includes('pistol save'))                                         return 'save';
  if (lower.includes('default') || lower.includes('slow')   ||
      lower.includes('spread'))                                              return 'default';

  return 'default';
}
